     1→package io.exoreaction.synthesis.telemetry;
     2→
     3→import com.slack.api.Slack;
     4→import com.slack.api.methods.MethodsClient;
     5→import com.slack.api.methods.response.conversations.ConversationsHistoryResponse;
     6→import com.slack.api.model.Message;
     7→
     8→import java.io.IOException;
     9→import java.nio.file.Files;
    10→import java.nio.file.Path;
    11→import java.time.Duration;
    12→import java.time.Instant;
    13→import java.util.*;
    14→import java.util.regex.Matcher;
    15→import java.util.regex.Pattern;
    16→
    17→/**
    18→ * Pilot approval service that checks whether a client UUID is approved.
    19→ *
    20→ * <p>The approval system works as follows:
    21→ * <ol>
    22→ *   <li>A Slack bot reads the approval channel (e.g., {@code #synthesis-pilots})</li>
    23→ *   <li>Messages in the channel contain approved UUIDs (any format -- the bot
    24→ *       extracts UUIDs via regex)</li>
    25→ *   <li>The approval status is cached locally at {@code ~/.synthesis/approval-status}</li>
    26→ *   <li>The cache is refreshed daily (first command after 24 hours triggers a refresh)</li>
    27→ * </ol>
    28→ *
    29→ * <p>Enforcement is <b>soft</b>: unapproved installations show a nag message but
    30→ * commands still execute normally.
    31→ *
    32→ * <p>Cache format ({@code ~/.synthesis/approval-status}):
    33→ * <pre>
    34→ * approved=true
    35→ * last_check=2026-02-14T12:00:00Z
    36→ * uuid=abc-123-def-456
    37→ * </pre>
    38→ *
    39→ * @see ApprovalConfig
    40→ */
    41→public class ApprovalService {
    42→
    43→    /** Cache file for approval status. */
    44→    public static final String STATUS_FILENAME = "approval-status";
    45→
    46→    /** How often to re-check approval (24 hours). */
    47→    public static final Duration REFRESH_INTERVAL = Duration.ofHours(24);
    48→
    49→    /** UUID regex pattern for extracting UUIDs from Slack messages. */
    50→    static final Pattern UUID_PATTERN = Pattern.compile(
    51→            "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
    52→            Pattern.CASE_INSENSITIVE
    53→    );
    54→
    55→    private final ApprovalConfig config;
    56→    private final Path statusPath;
    57→
    58→    // Cached state
    59→    private Boolean approved;
    60→    private Instant lastCheck;
    61→    private boolean welcomeShown;
    62→
    63→    /**
    64→     * Creates an ApprovalService with the given configuration.
    65→     */
    66→    public ApprovalService(ApprovalConfig config, Path homeDir) {
    67→        this.config = config;
    68→        this.statusPath = homeDir.resolve(ClientUUID.GLOBAL_DIR).resolve(STATUS_FILENAME);
    69→        this.approved = null;
    70→        this.lastCheck = null;
    71→        this.welcomeShown = false;
    72→        loadCache();
    73→    }
    74→
    75→    /**
    76→     * Creates an ApprovalService from the global configuration.
    77→     */
    78→    public static ApprovalService create() {
    79→        ApprovalConfig config = ApprovalConfig.load();
    80→        Path homeDir = Path.of(System.getProperty("user.home"));
    81→        return new ApprovalService(config, homeDir);
    82→    }
    83→
    84→    /**
    85→     * Creates an ApprovalService with a custom home directory (for testing).
    86→     */
    87→    public static ApprovalService create(Path homeDir) {
    88→        ApprovalConfig config = ApprovalConfig.load(ApprovalConfig.getConfigPath(homeDir));
    89→        return new ApprovalService(config, homeDir);
    90→    }
    91→
    92→    /**
    93→     * Checks whether the given UUID is approved for the pilot program.
    94→     *
    95→     * <p>Uses cached status if available and fresh (less than 24 hours old).
    96→     * If the cache is stale or missing, attempts a live check against the
    97→     * Slack channel. If the live check fails (network, config, etc.),
    98→     * falls back to the cached status or returns false.
    99→     *
   100→     * @param uuid the client UUID to check
   101→     * @return true if the UUID is approved
   102→     */
   103→    public boolean isApproved(String uuid) {
   104→        // If we have a fresh cache, use it
   105→        if (approved != null && !shouldRefresh()) {
   106→            return approved;
   107→        }
   108→
   109→        // Attempt refresh
   110→        if (config.isConfigured()) {
   111→            try {
   112→                refreshApprovalStatus(uuid);
   113→            } catch (Exception e) {
   114→                // Refresh failed -- fall back to cached value
   115→            }
   116→        }
   117→
   118→        return approved != null ? approved : false;
   119→    }
   120→
   121→    /**
   122→     * Returns true if the approval status cache is stale (older than 24 hours)
   123→     * or has never been checked.
   124→     */
   125→    public boolean shouldRefresh() {
   126→        if (lastCheck == null) return true;
   127→        return Duration.between(lastCheck, Instant.now()).compareTo(REFRESH_INTERVAL) > 0;
   128→    }
   129→
   130→    /**
   131→     * Refreshes the approval status by reading the Slack approval channel.
   132→     *
   133→     * <p>Reads the last 200 messages in the approval channel, extracts all UUIDs
   134→     * from the message text, and checks whether the given UUID is present.
   135→     *
   136→     * @param uuid the client UUID to look for
   137→     * @throws IOException if the Slack API call fails
   138→     */
   139→    public void refreshApprovalStatus(String uuid) throws IOException {
   140→        if (!config.isConfigured()) {
   141→            throw new IOException("Approval system not configured (missing bot token or channel ID)");
   142→        }
   143→
   144→        try {
   145→            Set<String> approvedUuids = fetchApprovedUUIDs();
   146→            this.approved = approvedUuids.contains(uuid.toLowerCase());
   147→            this.lastCheck = Instant.now();
   148→            saveCache(uuid);
   149→        } catch (Exception e) {
   150→            throw new IOException("Failed to check approval status: " + e.getMessage(), e);
   151→        }
   152→    }
   153→
   154→    /**
   155→     * Fetches the set of approved UUIDs from the Slack approval channel.
   156→     *
   157→     * <p>Reads up to 200 messages from the channel and extracts all UUID patterns
   158→     * from the message text. UUIDs are normalized to lowercase.
   159→     *
   160→     * @return set of approved UUID strings (lowercase)
   161→     */
   162→    public Set<String> fetchApprovedUUIDs() throws IOException {
   163→        Set<String> uuids = new HashSet<>();
   164→
   165→        try (Slack slack = Slack.getInstance()) {
   166→            MethodsClient methods = slack.methods(config.getSlackBotToken());
   167→
   168→            ConversationsHistoryResponse response = methods.conversationsHistory(r -> r
   169→                    .channel(config.getApprovalChannelId())
   170→                    .limit(200)
   171→            );
   172→
   173→            if (response.isOk() && response.getMessages() != null) {
   174→                for (Message message : response.getMessages()) {
   175→                    String text = message.getText();
   176→                    if (text != null) {
   177→                        Matcher matcher = UUID_PATTERN.matcher(text);
   178→                        while (matcher.find()) {
   179→                            uuids.add(matcher.group().toLowerCase());
   180→                        }
   181→                    }
   182→                }
   183→            }
   184→        } catch (Exception e) {
   185→            throw new IOException("Slack API error: " + e.getMessage(), e);
   186→        }
   187→
   188→        return uuids;
   189→    }
   190→
   191→    /**
   192→     * Returns whether this is a newly-approved installation that should see a welcome message.
