   211→    /**
   212→     * Returns the current Synthesis edition.
   213→     *
   214→     * <p>Editions are determined by the {@code SYNTHESIS_EDITION} environment variable,
   215→     * typically set by the launcher script ({@code bin/synthesis} or {@code bin/synthesis-core}).
   216→     *
   217→     * <p>Valid editions:
   218→     * <ul>
   219→     *   <li>{@code core} -- Air-gapped, no AI, no telemetry, no cloud</li>
   220→     *   <li>{@code pro} -- Full features including AI (default)</li>
   221→     *   <li>{@code enterprise} -- Air-gapped with daemon support</li>
   222→     *   <li>{@code ultimate} -- Full features with daemon support</li>
   223→     * </ul>
   224→     *
   225→     * @return the edition string, defaults to "pro" if not set
   226→     */
   227→    public static String getEdition() {
   228→        String edition = System.getenv("SYNTHESIS_EDITION");
   229→        return (edition != null && !edition.isBlank()) ? edition.toLowerCase() : "pro";
   230→    }
   231→
   232→    /**
   233→     * Returns {@code true} if running in air-gapped mode (no cloud connectivity).
   234→     *
   235→     * <p>In air-gapped mode:
   236→     * <ul>
   237→     *   <li>AI-dependent commands (ask, perspectives) are not registered</li>
   238→     *   <li>Telemetry is disabled</li>
   239→     *   <li>Update checks are skipped</li>
   240→     *   <li>Pilot approval checks are skipped</li>
   241→     * </ul>
   242→     *
   243→     * <p>Air-gapped editions: {@code core}, {@code enterprise}.
   244→     *
   245→     * @return true if the current edition is air-gapped
   246→     */
   247→    public static boolean isAirGapped() {
   248→        String edition = getEdition();
   249→        return "core".equals(edition) || "enterprise".equals(edition);
   250→    }
