   259→    public static void main(String[] args) {
   260→        boolean airGapped = isAirGapped();
   261→
   262→        // Initialize telemetry (async, non-blocking)
   263→        // In air-gapped mode, TelemetryService.create() returns a no-op instance
   264→        TelemetryService telemetry = airGapped
   265→                ? TelemetryService.createNoOp()
   266→                : TelemetryService.create();
   267→
   268→        // Skip pilot approval and update checks in air-gapped mode
   269→        if (!airGapped) {
   270→            // Check pilot approval status and show nag if not approved
   271→            checkPilotApproval(telemetry.getClientUuid());
   272→
   273→            // Background update check (non-blocking, daily)
   274→            Path synthesisHome = Path.of(System.getProperty("user.home"), ".synthesis");
   275→            UpdateChecker.checkInBackground(synthesisHome);
   276→
   277→            // Show any pending update notification from previous check
   278→            String firstArg = args.length > 0 ? args[0] : "";
   279→            if (!"update".equals(firstArg) && !"--version".equals(firstArg) && !"-V".equals(firstArg)) {
   280→                UpdateChecker.showPendingNotification(synthesisHome);
   281→            }
   282→        }
   283→
   284→        // Determine the command name for telemetry tracking
   285→        String commandName = args.length > 0 ? args[0] : "help";
   286→        long startTime = System.currentTimeMillis();
   287→
   288→        int exitCode;
   289→        SynthesisApp app = new SynthesisApp();
   290→        try {
   291→            CommandLine cmd = new CommandLine(app)
   292→                    .setExecutionExceptionHandler((ex, cmdLine, parseResult) -> {
   293→                        System.err.println("Error: " + ex.getMessage());
   294→                        return 1;
   295→                    });
   296→
   297→            // Install grouped command help renderer
   298→            installGroupedHelpRenderer(cmd);
   299→
   300→            // In air-gapped mode, remove AI-dependent commands
   301→            if (airGapped) {
   302→                for (String aiCommand : AI_COMMAND_NAMES) {
   303→                    cmd.getSubcommands().remove(aiCommand);
   304→                }
   305→            }
   306→
   307→            exitCode = cmd.execute(args);
   308→        } catch (Exception e) {
   309→            exitCode = 1;
   310→        }
   311→
   312→        // Report command execution (async, non-blocking)
   313→        long durationMs = System.currentTimeMillis() - startTime;
   314→        telemetry.reportCommand(commandName, exitCode == 0, durationMs);
   315→
   316→        // Allow pending telemetry events to be sent (max 2 seconds)
   317→        telemetry.shutdown();
   318→
   319→        // Flush any CLI-recorded metrics
   320→        app.shutdownMetrics();
   321→
   322→        // Close SynthesisDatabase if it was initialized (allows clean WAL checkpoint)
   323→        try {
   324→            SynthesisDatabase db = SynthesisDatabase.getDefaultIfExists();
   325→            if (db != null) db.close();
   326→        } catch (Exception ignored) {}
   327→
   328→        System.exit(exitCode);
   329→    }
