   331→    private static final java.util.LinkedHashMap<String, java.util.List<String>> HELP_GROUPS;
   332→    static {
   333→        HELP_GROUPS = new java.util.LinkedHashMap<>();
   334→        HELP_GROUPS.put("Core:", java.util.List.of(
   335→            "search", "maintain", "health", "init", "scan", "downloads"
   336→        ));
