   343→        ));
   344→        HELP_GROUPS.put("Workspace:", java.util.List.of(
   345→            "staging", "sweep", "prune", "ttl", "archive", "sync",
   346→            "describe", "feedback", "knowledge-graph", "structure", "evolution", "consolidate", "scatter", "naming"
   347→        ));
   348→        HELP_GROUPS.put("Admin:", java.util.List.of(
   349→            "update", "telemetry", "credentials", "org", "learn",
   350→            "status", "export", "graph", "cross-repo-deps", "which",
   351→            "list", "discover", "validate", "report", "upcoming",
   352→            "extract-slides", "migrate-repos", "export-skills", "trace",
