   357→    /**
   358→     * Installs the grouped command list renderer on the given {@link CommandLine}.
   359→     * Called from {@link #main(String[])} and available for testing.
   360→     */
   361→    public static void installGroupedHelpRenderer(CommandLine cmd) {
   362→        cmd.getHelpSectionMap().put(
   363→            picocli.CommandLine.Model.UsageMessageSpec.SECTION_KEY_COMMAND_LIST,
   364→            help -> renderGroupedCommandList(help)
   365→        );
   366→    }
   367→
   368→    private static String renderGroupedCommandList(picocli.CommandLine.Help help) {
   369→        java.util.Map<String, picocli.CommandLine> subcommands = help.commandSpec().subcommands();
   370→        if (subcommands.isEmpty()) return "";
   371→
   372→        StringBuilder sb = new StringBuilder();
   373→        java.util.Set<String> rendered = new java.util.HashSet<>();
   374→
   375→        // Column width for command names
   376→        int nameWidth = 16;
   377→
   378→        for (java.util.Map.Entry<String, java.util.List<String>> group : HELP_GROUPS.entrySet()) {
   379→            String groupHeader = group.getKey();
   380→            java.util.List<String> groupCommands = group.getValue();
   381→
   382→            // Check if any commands from this group are registered
   383→            boolean hasAny = groupCommands.stream().anyMatch(subcommands::containsKey);
   384→            if (!hasAny) continue;
   385→
   386→            sb.append("  ").append(groupHeader).append(System.lineSeparator());
   387→
   388→            for (String cmdName : groupCommands) {
   389→                picocli.CommandLine sub = subcommands.get(cmdName);
   390→                if (sub == null) continue;
   391→                String desc = "";
   392→                String[] descLines = sub.getCommandSpec().usageMessage().description();
   393→                if (descLines != null && descLines.length > 0) {
   394→                    desc = descLines[0];
   395→                    // Truncate to 50 chars
   396→                    if (desc.length() > 50) desc = desc.substring(0, 47) + "...";
   397→                }
   398→                sb.append(String.format("    %-" + nameWidth + "s %s%n", cmdName, desc));
   399→                rendered.add(cmdName);
   400→            }
   401→            sb.append(System.lineSeparator());
   402→        }
   403→
   404→        // Catch any commands not in any group
   405→        boolean hasOther = subcommands.keySet().stream().anyMatch(n -> !rendered.contains(n));
   406→        if (hasOther) {
   407→            sb.append("  Other:").append(System.lineSeparator());
   408→            subcommands.entrySet().stream()
   409→                .filter(e -> !rendered.contains(e.getKey()))
   410→                .sorted(java.util.Map.Entry.comparingByKey())
   411→                .forEach(e -> {
   412→                    String desc = "";
   413→                    String[] descLines = e.getValue().getCommandSpec().usageMessage().description();
   414→                    if (descLines != null && descLines.length > 0) {
   415→                        desc = descLines[0];
   416→                        if (desc.length() > 50) desc = desc.substring(0, 47) + "...";
   417→                    }
   418→                    sb.append(String.format("    %-" + nameWidth + "s %s%n", e.getKey(), desc));
   419→                });
   420→        }
   421→
   422→        return sb.toString();
   423→    }
