   427→     * instead of a hardcoded string.
   428→     */
   429→    static class VersionProvider implements CommandLine.IVersionProvider {
   430→        @Override
   431→        public String[] getVersion() {
   432→            return new String[] { Version.getFullVersion() };
   433→        }
