   436→    /**
   437→     * Checks pilot approval status and prints appropriate message.
   438→     *
   439→     * <p>Behavior:
   440→     * <ul>
   441→     *   <li>If approved: show welcome message (once per approval)</li>
   442→     *   <li>If not approved: show 1-line nag message (non-blocking)</li>
   443→     *   <li>If approval system not configured: silently skip</li>
   444→     * </ul>
   445→     *
   446→     * <p>Triggers a daily refresh of approval status (first command after 24 hours).
   447→     * This method never throws or blocks command execution.
   448→     */
   449→    private static void checkPilotApproval(String clientUuid) {
   450→        try {
   451→            if (clientUuid == null || "unknown".equals(clientUuid)) {
   452→                return;
   453→            }
   454→
   455→            ApprovalService approval = ApprovalService.create();
   456→            ApprovalConfig config = ApprovalConfig.load();
   457→
   458→            // If approval system is not configured (empty tokens), skip silently
   459→            if (!config.isConfigured()) {
   460→                return;
   461→            }
   462→
   463→            // If we have a cached status and it's not time to refresh, use cached
   464→            if (!approval.shouldRefresh() && approval.getCachedApproval() != null) {
   465→                boolean isApproved = approval.getCachedApproval();
   466→                if (isApproved && approval.shouldShowWelcome()) {
   467→                    System.err.println("  \u2713 Pilot approved -- Thank you for participating!");
   468→                }
   469→                return;
   470→            }
   471→
   472→            // Perform approval check
   473→            boolean isApproved = approval.isApproved(clientUuid);
   474→
   475→            if (isApproved) {
   476→                // Show welcome message once after approval
   477→                if (approval.shouldShowWelcome()) {
   478→                    System.err.println("  \u2713 Pilot approved -- Thank you for participating!");
   479→                }
   480→            } else {
   481→                // Nag message for unapproved installations (1 line, non-intrusive)
   482→                System.err.println("  \u26A0\uFE0F  Synthesis pilot approval pending. UUID: "
   483→                        + clientUuid + ". Contact maintainer for access.");
   484→            }
   485→        } catch (Exception e) {
   486→            // Approval check should never prevent command execution
   487→        }
   488→    }
   489→}
